script:
(function () {
  'use strict';
  // Habit savings: each habit's cost is converted to a monthly amount (per day x 365/12, per week x
  // 52/12) and multiplied by the cut percentage. The total is invested at the end of each month with monthly
  // compounding (annual rate / 12); an optional yearly price increase raises the monthly amount each year.
  // Checked under Node (scratchpad/tests/b7basic/vs_test.js): $100/month at 6% for 30 years = $100,451.50
  // (closed form); $10/day for a year at 0% = $3,650; $40/week cut 50% = $86.67/month; $100/month with a
  // 10% yearly rise at 0% for 2 years = $2,520; goal timing ($1,000 at $100/month, 0%) = 10 months.
  // ---- Habit savings maths ----
  var PER_MONTH = { day: 365 / 12, week: 52 / 12, month: 1 };
  var MAX_GOAL_MONTHS = 1200;

  // Monthly amount saved by cutting a habit that costs `cost` per `per` by `cutPct` percent.
  function monthlySaving(cost, per, cutPct) {
    return cost * (PER_MONTH[per] || 0) * cutPct / 100;
  }

  // Invest `monthly` at the end of each month, compounding monthly at annualRate/12. The monthly
  // amount rises by `rise` (decimal) at the start of each new year. Runs for `years` years, and
  // keeps going (up to 100 years) only to find when `goal` is first reached.
  function grow(monthly, annualRate, years, rise, goal) {
    var i = annualRate / 12, bal = 0, saved = 0, rows = [], goalMonth = 0, end = null;
    var limit = Math.max(years * 12, goal > 0 ? MAX_GOAL_MONTHS : 0);
    var yearSaved = 0;
    for (var m = 1; m <= limit; m++) {
      var dep = monthly * Math.pow(1 + rise, Math.floor((m - 1) / 12));
      bal = bal * (1 + i) + dep;
      saved += dep; yearSaved += dep;
      if (goal > 0 && !goalMonth && bal >= goal - 1e-9) goalMonth = m;
      if (m <= years * 12 && m % 12 === 0) {
        rows.push({ year: m / 12, yearSaved: yearSaved, saved: saved, balance: bal });
        yearSaved = 0;
      }
      if (m === years * 12) end = { balance: bal, saved: saved };
      if (end && (goalMonth || !(goal > 0))) break;
    }
    return { balance: end.balance, saved: end.saved, rows: rows, goalMonth: goalMonth };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money2 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var HABITS = [1, 2, 3];

  function val(id) {
    var input = document.getElementById(id);
    if (input.value.trim() === '') return input.validity && input.validity.badInput ? NaN : null;
    var v = parseFloat(input.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clear(id) { var b = document.getElementById(id); while (b.firstChild) b.removeChild(b.firstChild); return b; }
  function row(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (t) { var td = document.createElement('td'); td.textContent = t; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function update() {
    var error = document.getElementById('vsError'), msg = '';
    var habits = [];
    HABITS.forEach(function (n) {
      var cost = val('vsCost' + n), cut = val('vsCut' + n);
      if (cost === null) return;
      if (isNaN(cost) || cost < 0 || cost > 1e6) { msg = 'Enter habit costs of $0 or more.'; return; }
      if (cut === null) cut = 100;
      if (isNaN(cut) || cut < 0 || cut > 100) { msg = 'Enter a cut from 0% to 100%.'; return; }
      var per = document.getElementById('vsPer' + n).value;
      habits.push({ name: document.getElementById('vsHabit' + n).value, now: monthlySaving(cost, per, 100), save: monthlySaving(cost, per, cut) });
    });
    var rate = val('vsRate'), years = val('vsYears'), goal = val('vsGoal'), rise = val('vsPriceRise');
    if (goal === null) goal = 0;
    if (rise === null) rise = 0;
    if (!msg && (rate === null || isNaN(rate) || rate < 0 || rate > 30)) msg = 'Enter an annual return from 0% to 30%.';
    if (!msg && (years === null || isNaN(years) || years < 1 || years > 60)) msg = 'Enter 1 to 60 years.';
    if (!msg && (isNaN(goal) || goal < 0)) msg = 'Enter a goal of $0 or more, or leave it blank.';
    if (!msg && (isNaN(rise) || rise < 0 || rise > 20)) msg = 'Enter a yearly price increase from 0% to 20%.';
    if (!msg && !habits.length) msg = 'Enter what at least one habit costs you.';
    error.textContent = msg; error.hidden = !msg;
    if (msg) {
      ['vsValue', 'vsMonthly', 'vsYearly', 'vsGoalTime', 'vsNotSpent', 'vsGrowth', 'vsNowMonthly', 'vsAfterMonthly'].forEach(function (id) { set(id, '–'); });
      clear('vsByHabit'); clear('vsSchedule');
      return;
    }
    years = Math.round(years);
    var monthly = habits.reduce(function (s, h) { return s + h.save; }, 0);
    var now = habits.reduce(function (s, h) { return s + h.now; }, 0);
    var r = grow(monthly, rate / 100, years, rise / 100, goal);

    set('vsValueLabel', 'Invested value after ' + years + (years === 1 ? ' year' : ' years'));
    set('vsValue', money.format(r.balance));
    set('vsMonthly', money2.format(monthly));
    set('vsYearly', money.format(monthly * 12));
    set('vsGoalTime', goal <= 0 ? 'No goal set' : (r.goalMonth ? duration(r.goalMonth) : 'Over 100 years'));
    set('vsNotSpent', money.format(r.saved));
    set('vsGrowth', money.format(r.balance - r.saved));
    set('vsNowMonthly', money2.format(now));
    set('vsAfterMonthly', money2.format(now - monthly));

    var byHabit = clear('vsByHabit');
    habits.forEach(function (h) {
      var share = monthly > 0 ? h.save / monthly : 0;
      row(byHabit, [h.name, money2.format(h.save), money.format(r.balance * share)]);
    });
    var sched = clear('vsSchedule');
    r.rows.forEach(function (x) {
      row(sched, [String(x.year), money.format(x.yearSaved), money.format(x.saved), money.format(x.balance - x.saved), money.format(x.balance)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('vsForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
